import { MotiTransitionProp, MotiView } from 'moti'

const MOTI_TRANSITION_CONFIG: MotiTransitionProp = {
	type: 'timing',
	duration: 200
}

export const ButtonLeafLayout = ({
	children
}: {
	children: React.ReactNode
}) => {
	return (
		<MotiView
			from={{ opacity: 0, translateX: -10 }}
			animate={{ opacity: 1, translateX: 0 }}
			exit={{ opacity: 0, translateX: 10 }}
			transition={MOTI_TRANSITION_CONFIG}
			exitTransition={MOTI_TRANSITION_CONFIG}
		>
			{children}
		</MotiView>
	)
}
